actions.script:
try {
    zipBytes = Base64.getMimeDecoder().decode(zip as String)
    def OwnerDataTransfer = ec.resource.script('component://growerp/service/OwnerDataTransfer.groovy', null)
    manifest = OwnerDataTransfer.readZip(zipBytes).manifest
} catch (Exception e) {
    manifest = null
}

def created = ec.service.sync().name('create#growerp.general.OwnerDataTransfer')
    .parameters([ownerPartyId: ownerPartyId, direction: direction, status: 'QUEUED',
                 fileName: fileName, username: ec.user.username, createdDate: ec.user.nowTimestamp])
    .requireNewTransaction(true).call()
ownerDataTransferId = created.ownerDataTransferId
if (zipBytes) {
    File upload = new File(ec.factory.runtimePath + "/ownerData/${ownerDataTransferId}-upload.zip")
    upload.parentFile.mkdirs()
    upload.bytes = (byte[]) zipBytes
}

import groovy.json.JsonOutput

ec.artifactExecution.disableAuthz()
def job = ec.entity.find('growerp.general.OwnerDataTransfer')
        .condition('ownerDataTransferId', ownerDataTransferId).useCache(false).one()
if (job == null) return
// the async worker has no user: run as the one who asked
if (job.username) ec.user.internalLoginUser(job.username)
Closure update = { Map fields ->
    ec.service.sync().name('update#growerp.general.OwnerDataTransfer')
        .parameters(fields + [ownerDataTransferId: ownerDataTransferId])
        .requireNewTransaction(true).disableAuthz().call()
}
Closure progress = { String message -> update([progress: message]) }
update([status: 'RUNNING', progress: 'Started'])
File dir = new File(ec.factory.runtimePath + '/ownerData')
try {
    def OwnerDataTransfer = ec.resource.script('component://growerp/service/OwnerDataTransfer.groovy', null)
    def transfer = OwnerDataTransfer.newInstance(ec, progress)
    if (job.direction == 'EXPORT') {
        File zipFile = new File(dir, "${ownerDataTransferId}.zip")
        Map result = ec.transaction.runUseOrBegin(7200, 'Owner data download failed') {
            transfer.export(job.ownerPartyId, zipFile)
        }
        String day = ec.user.nowTimestamp.toLocalDateTime().toLocalDate().toString()
        update([status: 'DONE', progress: "${result.counts.values().sum() ?: 0} records, ${result.files} files".toString(),
                fileLocation: zipFile.path, fileName: "growerp-data-${job.ownerPartyId}-${day}.zip".toString(),
                countsJson: JsonOutput.toJson(result.counts), completedDate: ec.user.nowTimestamp])
    } else {
        File upload = new File(dir, "${ownerDataTransferId}-upload.zip")
        Map data = OwnerDataTransfer.readZip(upload.bytes)
        List conflicts = transfer.conflicts(data)
        if (conflicts) throw new IllegalStateException('Not loaded: ' + conflicts.join(', '))
        Map result = ec.transaction.runUseOrBegin(7200, 'Owner data upload failed') {
            transfer.load(data)
        }
        upload.delete()
        update([status: 'DONE', newOwnerPartyId: result.ownerPartyId,
                progress: "${result.counts.values().sum() ?: 0} records, ${result.files} files, ${result.skipped.size()} skipped".toString(),
                countsJson: JsonOutput.toJson(result.counts), completedDate: ec.user.nowTimestamp])
    }
} catch (Throwable t) {
    ec.logger.error("Owner data ${job.direction} ${ownerDataTransferId} failed", t)
    ec.message.clearErrors()
    new File(dir, "${ownerDataTransferId}-upload.zip").delete()
    update([status: 'FAILED', errorMessage: (t.message ?: t.toString()).take(4000),
            completedDate: ec.user.nowTimestamp])
}

File zipFile = new File(job.fileLocation as String)
if (zipFile.exists()) {
    zip = Base64.getEncoder().encodeToString(zipFile.bytes)
    fileName = job.fileName
}
